import json
from pathlib import Path

ROOT=Path('/workspace/sites/olympiad-atlas')
new=[]
def add(year,num,diff,topic,tags,statement,reason,comp='CMO',shared=None):
    base='https://cms.math.ca/wp-content/uploads/'+('2019/07/' if year<2017 else '2024/03/')
    prefix='j' if comp=='CJMO' else ''
    src=base+prefix+'exam'+str(year)+'.pdf'
    sol=base+prefix+'sol'+str(year)+'.pdf'
    appearances=[dict(competition=comp,year=year,number=str(num))]
    if shared: appearances.append(dict(competition='CJMO',year=year,number=str(shared)))
    new.append(dict(id=f'ca-{comp.lower()}-{year}-{num}',country='Canada',competition=comp,year=year,number=str(num),statement=statement,solution=f'[View the official worked solution PDF]({sol}).',sourceUrl=src,solutionUrl=sol,solutionKind='source-link',topic=topic,tags=tags.split('|'),difficulty=diff,ratingReason=reason,reviewStatus='individually-assessed',notes='Mathematical statement restated in original wording. Official solution reviewed; linked rather than reproduced.',appearances=appearances))

add(2020,1,4.5,'Combinatorics','Induction|Extremal principle|Powers',r'For a set $S$ of $n\ge3$ distinct positive real numbers, count the distinct integer powers of $3$ expressible as the sum of three different elements of $S$. Prove that the largest possible count is $n-2$.','Removing the largest element is the key: every triple containing it has sum strictly between x and 3x, so removes at most one power of three. The induction is short once this extremal choice is found, and a construction establishes sharpness.',shared=3)
add(2020,2,5,'Geometry','Tangency|Area|Rhombus',r'A rhombus $ABCD$ has an inscribed circle. Points $P\in AB$ and $Q\in AD$ vary so that the segment $PQ$ is tangent to this circle. Prove that the area of $\triangle CPQ$ does not depend on $P$ and $Q$.','The efficient route converts the area of the tangential pentagon into inradius times semiperimeter and subtracts two triangles of height twice the inradius. Equal tangent lengths then cancel the moving terms; discovering the useful area decomposition is the main step.',shared=4)
add(2020,3,7,'Combinatorics','Construction|Subset sums|Counting',r'Can a finite collection of coins, all with different positive integer values, have exactly $2020$ subsets whose values sum to $2020$? Prove your answer.','A successful construction starts with eleven small coins and complementary large coins, giving 2047 representations, then removes large coins corresponding to precisely 27 small subset sums. Both engineering the construction and checking the exact count require substantial work.',shared=5)
add(2020,4,6.5,'Number theory','Perfect powers|Counting|Asymptotics',r'List all positive integer perfect powers in increasing order, without repetition, as $a_1<a_2<a_3<\cdots$, where a perfect power is $u^v$ for positive integers $u,v$ with $v\ge2$. Prove that $9999$ divides $a_{m+1}-a_m$ for infinitely many positive integers $m$.','One first targets consecutive squares whose difference is divisible by 9999. The decisive argument bounds nonsquare perfect powers by O(X^(1/3) log X), too few to occupy every selected square gap. This combines a modular construction with a less routine counting comparison.')
add(2020,2,6.5,'Combinatorics','Construction|Paths|Geometry',r'Starting at the origin, a person draws connected straight segments of lengths $1,2,3,\ldots$, in that order, without lifting the pen. Segments may overlap or cross. Can the union of the segments after finitely many steps be exactly the boundary of an $N\times N$ square for a positive integer $N$?','The challenge is an exact construction that never draws outside the square boundary. Consecutive opposite segments act as unit shifts, allowing the four sides to be completed; the official constructions require careful planning and endpoint checks.',comp='CJMO')

add(2019,1,6.5,'Geometry','Construction|Circumcentres|Iteration',r'Begin with the vertices $A,B,C$ of an equilateral triangle of side $6$. You may repeatedly add the circumcentre of any nondegenerate triangle whose vertices have already been obtained. Prove that you can obtain two points more than $7$ apart, and then prove that you can obtain two points more than $2019$ apart.','A short chain of circumcentre constructions produces a point at distance sqrt(52) from an original vertex. The second part requires rotating that construction to obtain a larger equilateral triangle and iterating a genuine scale increase.')
add(2019,2,4,'Number theory','Divisibility|Prime factorisation|Perfect powers',r'Let $a,b$ be positive integers such that $a^2+3ab+3b^2-1$ divides $a+b^3$. Show that $a^2+3ab+3b^2-1$ is divisible by the cube of an integer greater than $1$.','Multiplying the divisor by a exposes (a+b)^3. If the divisor were cube-free, its prime exponents would force it to divide (a+b)^2, contradicting its size. Two clean but non-obvious observations suffice.')
add(2019,3,5,'Combinatorics','Bijections|Lattice paths|Chessboards',r'Colour a $2m\times2n$ board like a chessboard, where $m,n$ are positive integers. In how many ways can $mn$ counters be placed on white squares, at most one per square, with no two counters on diagonally adjacent squares?','Partitioning into 2-by-2 blocks forces exactly one counter per block. The two possible positions then propagate in opposite directions and are encoded by a monotone boundary path, yielding binomial(m+n,m). Recognising this bijection is the main difficulty.')
add(2019,4,7,'Algebra','Inequalities|Polynomials|Telescoping',r'Let $n>1$ be an integer and let $a_0,a_1,\ldots,a_n$ be real numbers with $a_1=a_{n-1}=0$. Prove that, for every real $k$, $\displaystyle |a_0|-|a_n|\le\sum_{i=0}^{n-2}|a_i-ka_{i+1}-a_{i+2}|$.','The recurrence-shaped expression suggests factoring a second-order difference operator. Choosing a quadratic root of modulus at most one produces a weighted telescope or polynomial identity; the boundary conditions then give the inequality. Finding this auxiliary parameter is a substantial insight.')

add(2018,1,5,'Combinatorics','Invariants|Induction|Dyadic rationals',r'Place $n$ tokens in the plane, allowing coincidences. A move selects two tokens and moves both to the midpoint of their positions. Prove that every starting arrangement can be brought to one common point after finitely many moves if and only if $n$ is a power of $2$.','The sum of position vectors is invariant, while initially integral coordinates remain dyadic rational. A one-token-versus-the-rest example supplies necessity; a separate doubling induction gives sufficiency. Both directions require selecting the correct invariant and construction.')
add(2018,2,4,'Geometry','Cyclic quadrilaterals|Congruence|Perpendicular bisectors',r'Points $A,B,C,D,E$ occur in that clockwise order on a circle, with $AE=DE$. Put $P=AC\cap BD$. On line $AB$, choose $Q$ so that $A$ lies between $B$ and $Q$ and $AQ=DP$. On line $CD$, choose $R$ so that $D$ lies between $C$ and $R$ and $DR=AP$. Prove $PE\perp QR$.','The construction is designed for three SAS congruences: first show PQ=PR, then EQ=ER using the equal chords. Recognising the common perpendicular bisector gives a short solution with a modest cyclic angle chase.')
add(2018,3,6.5,'Number theory','Divisors|Graph theory|Construction|Parity',r'Call two positive integers prime-related when one is a prime multiple of the other. Determine all positive integers $n$ having at least three positive divisors such that all their divisors can be placed in a circle, each used once, with adjacent numbers prime-related.','Necessary restrictions come from parity of prime-exponent changes and the neighbours of 1. Sufficiency requires constructing a cycle through an exponent grid with an even side, then carefully extending it when new prime factors are added; the construction is the harder half.')

add(2017,2,6.5,'Number theory','Functional equations|Divisor function|Descent',r'A function $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ satisfies $f(f(n))=d(n)$ for every positive integer $n$, where $d(n)$ counts the positive divisors of $n$. Prove that $f(p)$ is prime whenever $p$ is prime.','Commuting f with the divisor-count function reduces the task to proving f(2)=2. That requires a minimal-preimage descent plus a separate exclusion of f(2)=1 using prime squares. The nested functional condition makes these reductions nontrivial.')
add(2017,3,4,'Combinatorics','Involutions|Parity|Subsets',r'A nonempty subset $T\subseteq\{1,\ldots,n\}$ is balanced if its arithmetic mean equals its median. For an even-sized set the median is the average of its two middle elements. Prove that, for every positive integer $n$, the number of balanced subsets is odd.','Reflecting t to n+1-t swaps sets whose median is greater than their mean with those whose median is smaller. Subtracting those equal counts from the odd total proves the claim. The main work is identifying the right involution, with little calculation.')
add(2017,4,6,'Geometry','Equilateral triangles|Circumcentres|Parallelograms',r'Inside a parallelogram $ABCD$, points $P,Q$ are chosen so that $ABP$ and $BCQ$ are equilateral triangles. Prove that the perpendicular to $DP$ through $P$ and the perpendicular to $DQ$ through $Q$ intersect on the altitude from $B$ in $\triangle ABC$.','Congruent triangles first show DPQ is equilateral. Introducing its circumcentre then gives another congruence and an equal-distance relation to A and C; the desired altitude follows from a midpoint argument. This is a linked synthetic chain rather than a single angle chase.')
add(2017,5,6.5,'Geometry','Extremal principle|Projection|Pigeonhole principle',r'One hundred circles of radius $1$ lie in the plane. Every triangle formed by three of their centres has area at most $2017$. Prove that some line intersects at least three of the circles.','Choose two farthest centres at distance d. Area bounds put perpendicular projections in an interval of length at most min(d,8068/d), below 90. Averaging overlap of the projected diameter intervals then gives a triple intersection. The key is combining diameter and area bounds in one direction.')

add(2015,1,5.5,'Algebra','Functional equations|Induction|Integer inequalities',r'Determine all functions $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ satisfying $(n-1)^2<f(n)f(f(n))<n^2+n$ for every positive integer $n$.','Strong induction forces f(n)=n. A value below n immediately contradicts the lower bound; a value above n forces its image below n and creates a second contradiction. The useful double application of the bounds is the central step.')
add(2015,2,4.5,'Geometry','Orthocentre|Power of a point|Inequalities',r'An acute triangle $ABC$ has altitudes $AD,BE,CF$ and orthocentre $H$. Prove that $\displaystyle\frac{AB\cdot AC+BC\cdot BA+CA\cdot CB}{AH\cdot AD+BH\cdot BE+CH\cdot CF}\le2$.','Power of a point or projections convert each orthocentre-altitude product to a side projection. Their sum is half the sum of squared side lengths; the remaining inequality is a sum of three squares. The geometric identity carries most of the difficulty.')
add(2015,3,6.5,'Combinatorics','Extremal counting|Grid paths|Construction',r'A turtle traverses a $(4n+2)\times(4n+2)$ board by moves between squares sharing a side, starting at a corner, visiting every square exactly once, and finally returning to its starting square. Find the greatest integer $k$ such that every such route enters at least one row or column at least $k$ separate times.','Counting entries into all rows and columns gives a mean of 2n+1, and the edge columns force a strict inequality. Sharpness at 2n+2 needs a carefully arranged four-quadrant Hamiltonian cycle, so the full solution is substantially harder than the bound alone.')
add(2015,4,7,'Geometry','Tangency|Similar triangles|Circumcentres',r'Let $ABC$ be acute with circumcentre $O$. A circle $\Gamma$, whose centre lies on the altitude from $A$, passes through $A$ and intersects $AB,AC$ again at $P,Q$. Given $BP\cdot CQ=AP\cdot AQ$, prove that $\Gamma$ is tangent to the circumcircle of $BOC$.','The auxiliary point diametrically opposite O on the BOC circle identifies the candidate contact point. A sequence of angle-bisector and similarity arguments puts it on Gamma, and parallel centre lines establish tangency. Several coordinated constructions place it at the upper edge of the target.')

add(2016,1,4.5,'Combinatorics','Construction|Averages|Induction',r'The numbers $1,2,\ldots,2016$ are on a board. A move removes any two numbers and writes their arithmetic mean instead. After $2015$ moves only one number remains. Prove that a suitable sequence of moves can make the final number (a) $2$ and (b) $1000$.','A tailored first merge at the large end creates a pattern that can be peeled down to 2. Applying the same construction, and its reflected version, to two blocks around 1000 handles the second part. The constructive pattern is more important than calculation.')
add(2016,2,5.5,'Algebra','Systems of equations|Quadratics|AM-GM',r'Find every real $10$-tuple $(v_1,\ldots,v_{10})$ satisfying $\displaystyle v_i=1+\frac{6v_i^2}{v_1^2+v_2^2+\cdots+v_{10}^2}$ for $i=1,\ldots,10$.','Introducing the sum of squares shows all ten variables are roots of one quadratic. AM-GM applied with the multiplicities forces a 9-to-1 split unless all are equal; summing the original equations fixes the two values. The multiplicity restriction is the key additional insight.')
add(2016,3,6,'Algebra','Integer polynomials|Divisibility|Primes|Degree arguments',r'Find all polynomials $P$ with integer coefficients for which $P(P(n)+n)$ is a positive prime for infinitely many integers $n$.','Polynomial divisibility gives P(n) dividing P(P(n)+n). Apart from finitely many unit values, an infinite subsequence therefore gives one of two polynomial identities; comparison of degrees reduces to linear and constant cases. The prime-value condition must be converted into an identity, not estimated.')

data=json.loads((ROOT/'data/americas.json').read_text())
ids={p['id'] for p in new}
data=[p for p in data if p['id'] not in ids]+new
(ROOT/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
coverage=json.loads((ROOT/'research/americas-coverage.json').read_text())
full={('CMO',2020):[4.5,5,7,6.5,8],('CJMO',2020):[3,6.5,4.5,5,7],('CMO',2019):[6.5,4,5,7,8],('CMO',2018):[5,4,6.5,7.5,8.5],('CMO',2017):[3.5,6.5,4,6,6.5],('CMO',2016):[4.5,5.5,6,9,8.5],('CMO',2015):[5.5,4.5,6.5,7,8]}
coverage['fullyScreened']=[r for r in coverage['fullyScreened'] if (r['competition'],r['year']) not in full]
for (comp,year),ratings in full.items():coverage['fullyScreened'].append(dict(competition=comp,year=year,ratings=ratings,source='https://cms.math.ca/competitions/cmo/'))
coverage['papersScreened']=len(coverage['fullyScreened'])
coverage['problemAppearancesScreened']=sum(len(r['ratings']) for r in coverage['fullyScreened']+coverage['partiallyScreened'])
coverage['uniqueIncluded']=len(data)
coverage['gaps'][0]='Canada: CMO before 2015 is not yet reviewed. All CJMO 2020–2026 and CMO 2015–2026 papers are fully screened.'
(ROOT/'research/americas-coverage.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2)+'\n')
print(f'Added {len(new)}; Americas now {len(data)}')
